UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 58, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 59, 7, NULL::text),(3, 187, 50, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 241, 1244, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='7b28916c-98c6-5d5a-9beb-c5b66385deda' AND md5(a.contenido)='3358cc5af00a285eb0523256344e5c2b' RETURNING a.id,md5(a.contenido) hash;